-- Local-only source baseline generated from the JPA entity model on 2026-09-23,
-- then rolled back to the pre-V1/V2/V3/V4 shape so those migrations are exercised.
-- It is immutable once committed. Production reconciliation is a Task 14 release gate.
create table appointments (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, scheduled_at timestamp(6) with time zone not null, shop_id bigint not null, user_id bigint not null, status varchar(20) not null, note text, primary key (id));
create table banners (is_active boolean not null, sort_order integer not null, category_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, image_url varchar(1024), subtitle varchar(255), title varchar(255) not null, primary key (id));
create table blog_categories (created_at timestamp(6), id bigint generated by default as identity, description varchar(255), name varchar(255) not null unique, slug varchar(255) not null unique, primary key (id));
create table blogs (is_featured boolean, reading_time_minutes integer, author_id bigint, category_id bigint, created_at timestamp(6), id bigint generated by default as identity, updated_at timestamp(6), view_count bigint, content TEXT not null, meta_description TEXT, meta_title varchar(255), slug varchar(255) not null unique, status varchar(255) not null check ((status in ('DRAFT','PUBLISHED'))), summary TEXT, thumbnail_url varchar(255), title varchar(255) not null, primary key (id));
create table bookmarks (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint, shop_id bigint, user_id bigint not null, primary key (id));
create table campaign_products (campaign_id bigint not null, product_id bigint not null);
create table campaigns (is_active boolean not null, created_at timestamp(6) with time zone not null, ends_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, title varchar(255) not null, primary key (id));
create table cart_items (qty integer not null, saved_for_later boolean not null, cart_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, variant_id bigint not null, primary key (id), constraint uq_cart_variant unique (cart_id, variant_id));
create table carts (created_at timestamp(6) with time zone not null, discount_id bigint, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
create table categories (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, name varchar(120) not null, slug varchar(140) not null unique, primary key (id));
create table cities (is_active boolean not null, id bigint generated by default as identity, name varchar(120) not null, province varchar(120), primary key (id));
create table community_comments (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, post_id bigint not null, user_id bigint not null, author_name varchar(120), body text not null, primary key (id));
create table community_posts (comment_count integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, author_name varchar(120), body text not null, primary key (id));
create table conversations (created_at timestamp(6) with time zone not null, customer_user_id bigint not null, id bigint generated by default as identity, last_message_at timestamp(6) with time zone, shop_id bigint not null, last_message_preview varchar(200), primary key (id), constraint uq_conversation_customer_shop unique (customer_user_id, shop_id));
create table discounts (is_active boolean not null, max_discount_amount numeric(38,2), min_order_amount numeric(38,2), usage_count integer not null, usage_limit integer, value numeric(38,2) not null, created_at timestamp(6) with time zone not null, end_date timestamp(6) with time zone, id bigint generated by default as identity, start_date timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, code varchar(255) not null unique, type varchar(255) not null check ((type in ('PERCENTAGE','FIXED_AMOUNT'))), primary key (id));
create table escrows (amount numeric(15,0) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint, released_at timestamp(6) with time zone, user_id bigint not null, status varchar(20) not null, primary key (id));
create table events (active boolean not null, created_at timestamp(6) with time zone not null, event_date timestamp(6) with time zone not null, id bigint generated by default as identity, location_id bigint, title varchar(160) not null, description text, primary key (id));
create table favorites (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, primary key (id), constraint uc_user_product unique (user_id, product_id));
create table flash_sales (active boolean not null, discount_percent integer not null, sold_count integer not null, stock_limit integer not null, ends_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, starts_at timestamp(6) with time zone not null, primary key (id));
create table gift_cards (balance numeric(15,0) not null, initial_amount numeric(15,0) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, owner_user_id bigint, code varchar(20) not null, primary key (id), constraint uq_giftcard_code unique (code));
create table group_buy_participants (created_at timestamp(6) with time zone not null, group_buy_id bigint not null, id bigint generated by default as identity, user_id bigint not null, primary key (id), constraint uq_groupbuy_user unique (group_buy_id, user_id));
create table group_buys (active boolean not null, current_count integer not null, target_count integer not null, unit_price numeric(15,0) not null, ends_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, primary key (id));
create table inventory (on_hand integer not null, reserved integer not null, version integer not null, updated_at timestamp(6) with time zone not null, variant_id bigint not null, primary key (variant_id));
create table live_sessions (viewer_count integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, pinned_product_id bigint, shop_id bigint, status varchar(20) not null, shop_name varchar(120), title varchar(160) not null, primary key (id));
create table locations (floor_count integer not null, lat float(53), lng float(53), city_id bigint, id bigint generated by default as identity, kind varchar(20) not null check ((kind in ('PASSAGE','BAZAAR','STREET'))), name varchar(180) not null, address varchar(255), map_image_url text, primary key (id));
create table loyalty_accounts (points integer not null, id bigint generated by default as identity, user_id bigint not null, tier varchar(20) not null, primary key (id), constraint uq_loyalty_user unique (user_id));
create table marketplace_order_items (line_total numeric(15,0) not null, quantity integer not null, unit_price numeric(15,0) not null, id bigint generated by default as identity, order_id bigint not null, product_id bigint, product_name varchar(200) not null, primary key (id));
create table marketplace_orders (total_amount numeric(15,0) not null, created_at timestamp(6) with time zone not null, customer_user_id bigint not null, id bigint generated by default as identity, shop_id bigint not null, status varchar(20) not null check ((status in ('PENDING','CONFIRMED','PREPARING','READY','COMPLETED','CANCELLED'))), note text, primary key (id));
create table messages (conversation_id bigint not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, sender_user_id bigint not null, body text not null, primary key (id));
create table notifications (read boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, title varchar(160) not null, body text, primary key (id));
create table offers (amount numeric(15,0) not null, created_at timestamp(6) with time zone not null, customer_user_id bigint not null, id bigint generated by default as identity, product_id bigint, shop_id bigint not null, status varchar(20) not null check ((status in ('PENDING','ACCEPTED','REJECTED'))), message text, primary key (id));
create table option_type (id bigint generated by default as identity, name varchar(100) not null unique, primary key (id));
create table option_value (id bigint generated by default as identity, option_type_id bigint not null, value varchar(100) not null, primary key (id));
create table order_items (qty integer not null, unit_price_snapshot numeric(12,2) not null, id bigint generated by default as identity, order_id bigint not null, variant_id bigint not null, title_snapshot varchar(255) not null, options_snapshot jsonb, primary key (id));
create table orders (gateway_paid_amount numeric(12,2) default 0 not null, shipping_price numeric(12,2) not null, subtotal_price numeric(12,2) not null, total_price numeric(12,2) not null, wallet_paid_amount numeric(12,2) default 0 not null, created_at timestamp(6) with time zone not null, delivered_at timestamp(6) with time zone, id bigint generated by default as identity, shipped_at timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('PLACED','PROCESSING','SHIPPING','COMPLETED','CANCELLED'))), shipping_carrier varchar(80), tracking_code varchar(120), address_snapshot jsonb not null, primary key (id));
create table parking_sessions (fee numeric(15,0) not null, paid boolean not null, created_at timestamp(6) with time zone not null, entered_at timestamp(6) with time zone not null, exited_at timestamp(6) with time zone, id bigint generated by default as identity, user_id bigint not null, spot varchar(40) not null, primary key (id));
create table payments (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint, updated_at timestamp(6) with time zone not null, wallet_transaction_id bigint, status varchar(20) not null check ((status in ('PENDING','SUCCESS','FAILED'))), authority varchar(100) not null, ref_id varchar(100), primary key (id));
create table price_alerts (active boolean not null, target_price numeric(15,0) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, primary key (id));
create table product_images (sort_order integer not null, id bigint generated by default as identity, product_id bigint not null, url text not null, primary key (id));
create table product_questions (is_new boolean not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, product_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, content text not null, primary key (id));
create table product_reviews (is_new boolean not null, rating integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, parent_id bigint, product_id bigint not null, updated_at timestamp(6) with time zone not null, user_id bigint not null, comment text not null, primary key (id));
create table product_variant_option_values (option_value_id bigint not null, product_variant_id bigint not null, primary key (option_value_id, product_variant_id));
create table product_variants (compare_at_price numeric(12,2), discounted_price numeric(12,2), is_active boolean not null, price numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint not null, updated_at timestamp(6) with time zone not null, sku varchar(80) not null unique, primary key (id));
create table product_videos (sort_order integer not null, id bigint generated by default as identity, product_id bigint not null, url text not null, primary key (id));
create table products (base_price numeric(12,2), discounted_price numeric(12,2), is_active boolean not null, category_id bigint, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, brand varchar(120), slug varchar(280) not null unique, description text, title varchar(255) not null, attributes jsonb, primary key (id));
create table rasteh_locations (location_id bigint not null, rasteh_id bigint not null, primary key (location_id, rasteh_id));
create table rastehs (sort_order integer not null, id bigint generated by default as identity, color_oklch varchar(60), icon_key varchar(60), label varchar(120) not null, primary key (id));
create table recently_viewed (id bigint generated by default as identity, product_id bigint not null, user_id bigint not null, viewed_at timestamp(6) with time zone not null, primary key (id), constraint uc_recently_viewed_user_product unique (user_id, product_id));
create table referrals (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, invitee_user_id bigint, inviter_user_id bigint not null, code varchar(16) not null, reward_status varchar(20) not null, primary key (id));
create table refresh_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, revoked_at timestamp(6) with time zone, user_id bigint not null, token_hash varchar(64) not null unique, primary key (id));
create table reports (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, target_id bigint not null, user_id bigint not null, status varchar(20) not null, target_type varchar(20) not null, reason text, primary key (id));
create table return_requests (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, order_id bigint not null, user_id bigint not null, status varchar(20) not null, reason text, primary key (id));
create table reviews (rating integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, shop_id bigint not null, user_id bigint not null, author_name varchar(120), comment text, primary key (id), constraint uq_review_user_shop unique (user_id, shop_id));
create table shop_products (active boolean not null, discount_percent integer, old_price numeric(15,0), price numeric(15,0) not null, stock integer not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, shop_id bigint not null, emoji varchar(16), condition varchar(20) not null check ((condition in ('NEW','USED','REFURBISHED'))), category_name varchar(120), name varchar(180) not null, description text, image_url text, primary key (id));
create table shops (accepts_offers boolean not null, has_chat boolean not null, map_x float(53), map_y float(53), rating numeric(3,2) not null, reviews_count integer not null, sales_count integer not null, verified boolean not null, approved_at timestamp(6) with time zone, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, location_id bigint, owner_user_id bigint not null, rasteh_id bigint, emoji varchar(16), status varchar(20) not null check ((status in ('PENDING','APPROVED','REJECTED','SUSPENDED'))), type varchar(20) not null check ((type in ('BUYABLE','VISIT_ONLY'))), phone varchar(30), floor varchar(40), category varchar(120), cover_style varchar(120), name varchar(180) not null, about text, address varchar(255), cover_url text, logo_url text, working_hours_json text, primary key (id));
create table stories (is_active boolean not null, category_id bigint, created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, id bigint generated by default as identity, product_id bigint, media_type varchar(20) not null check ((media_type in ('IMAGE','VIDEO'))), title varchar(100), blog_slug varchar(200), media_url varchar(500) not null, link_type varchar(20) default 'NONE' not null, primary key (id));
create table subscriptions (active boolean not null, expires_at timestamp(6) with time zone, id bigint generated by default as identity, user_id bigint not null, plan varchar(20) not null, primary key (id), constraint uq_subscription_user unique (user_id));
create table users (is_active boolean not null, postal_code integer, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, otp_expiry timestamp(6) with time zone, reset_password_token_expiry timestamp(6) with time zone, updated_at timestamp(6) with time zone not null, city varchar(50), first_name varchar(50), last_name varchar(50), email varchar(255) not null unique, otp_code varchar(255), password_hash varchar(255) not null, phone varchar(255) not null unique, reset_password_token varchar(255), role varchar(255) not null check ((role in ('CUSTOMER','VENDOR','ADMIN','SUPERADMIN'))), primary key (id));
create table vendor_category_modes (category_id bigint, id bigint generated by default as identity, shop_id bigint not null, mode varchar(20) not null check ((mode in ('SHOWCASE','COMMERCE'))), primary key (id), constraint uq_shop_category unique (shop_id, category_id));
create table wallet_transactions (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, wallet_id bigint not null, type varchar(20) not null check ((type in ('DEPOSIT','WITHDRAWAL','PURCHASE','REFUND','ADJUSTMENT'))), description varchar(255), reference_id varchar(255), primary key (id));
create table wallets (balance numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null unique, primary key (id));
create table warranties (created_at timestamp(6) with time zone not null, id bigint generated by default as identity, user_id bigint not null, valid_until timestamp(6) with time zone, serial varchar(80), title varchar(160) not null, primary key (id));
create table withdrawal_requests (amount numeric(12,2) not null, created_at timestamp(6) with time zone not null, id bigint generated by default as identity, updated_at timestamp(6) with time zone not null, user_id bigint not null, status varchar(20) not null check ((status in ('PENDING','APPROVED','PAID','REJECTED'))), iban varchar(26) not null, admin_note varchar(255), primary key (id));
create index idx_banners_active on banners (is_active);
create index idx_banners_sort on banners (sort_order);
create index idx_campaigns_active on campaigns (is_active);
create index idx_campaigns_ends_at on campaigns (ends_at);
create index idx_cart_items_cart on cart_items (cart_id);
create index idx_cart_items_variant on cart_items (variant_id);
